// PS4GL_GNM self-test: checks vertex array objects, glGetError and glReadPixels on the console.
// The screen turns green when every check passes and red when one fails.
// Details are written to /data/ps4gl/log.txt.
#include <stdint.h>
#include <string.h>
#include "ps4gl.h"
#include "sample_shaders.h"		// generated by build.py

static int s_passed, s_failed;
static GLuint s_prog;
static GLint s_aPos, s_aColor, s_uOffset;

static void Check( const char *name, bool ok )
{
	ps4glLog( "test %s: %s", ok ? "PASS" : "FAIL", name );
	if ( ok ) s_passed++; else s_failed++;
}

static bool Near( const uint8_t *p, int r, int g, int b, int a )
{
	const int want[4] = { r, g, b, a };
	for ( int i = 0; i < 4; i++ )
		if ( p[i] < want[i] - 2 || p[i] > want[i] + 2 ) return false;
	return true;
}

// ---- drawing helpers ----
struct Vertex { float x, y, z, r, g, b; };

static GLuint MakeBuffer( GLenum target, const void *data, size_t size )
{
	GLuint b;
	glGenBuffers( 1, &b );
	glBindBuffer( target, b );
	glBufferData( target, (GLsizeiptr)size, data, GL_STATIC_DRAW );
	return b;
}

static GLuint MakeQuad( float x0, float y0, float x1, float y1, float r, float g, float b )
{
	const Vertex v[6] =
	{
		{ x0, y0, 0, r, g, b }, { x1, y0, 0, r, g, b }, { x1, y1, 0, r, g, b },
		{ x0, y0, 0, r, g, b }, { x1, y1, 0, r, g, b }, { x0, y1, 0, r, g, b },
	};
	return MakeBuffer( GL_ARRAY_BUFFER, v, sizeof( v ) );
}

static void UseQuad( GLuint vb )
{
	glBindBuffer( GL_ARRAY_BUFFER, vb );
	glEnableVertexAttribArray( s_aPos );
	glEnableVertexAttribArray( s_aColor );
	glVertexAttribPointer( s_aPos, 3, GL_FLOAT, GL_FALSE, sizeof( Vertex ), (const void *)0 );
	glVertexAttribPointer( s_aColor, 3, GL_FLOAT, GL_FALSE, sizeof( Vertex ), (const void *)12 );
}

static void ClearWhite()
{
	glClearColor( 1, 1, 1, 1 );
	glClear( GL_COLOR_BUFFER_BIT );
}

static bool PixelIs( int x, int y, int r, int g, int b )
{
	uint8_t px[4] = { 1, 2, 3, 4 };
	glReadPixels( x, y, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, px );
	return Near( px, r, g, b, 255 );
}

// ---- glGetError ----
static void TestErrors()
{
	uint8_t px[16];
	Check( "no error after setup", glGetError() == GL_NO_ERROR );
	glDrawArrays( 0x7F, 0, 3 );
	Check( "bad draw mode gives INVALID_ENUM", glGetError() == GL_INVALID_ENUM );
	Check( "reading the error clears it", glGetError() == GL_NO_ERROR );
	glViewport( 0, 0, -1, 1 );
	glDrawArrays( 0x7F, 0, 3 );
	Check( "the first error is kept", glGetError() == GL_INVALID_VALUE );
	Check( "only one error is stored", glGetError() == GL_NO_ERROR );
	glVertexAttribPointer( 99, 3, GL_FLOAT, GL_FALSE, 0, NULL );
	Check( "bad attribute gives INVALID_VALUE", glGetError() == GL_INVALID_VALUE );
	glUseProgram( 123456 );
	Check( "unknown program gives INVALID_VALUE", glGetError() == GL_INVALID_VALUE );
	glBindVertexArray( 123456 );
	Check( "unknown VAO gives INVALID_OPERATION", glGetError() == GL_INVALID_OPERATION );
	glReadPixels( 0, 0, 1, 1, GL_RGBA, GL_FLOAT, px );
	Check( "bad read type gives INVALID_ENUM", glGetError() == GL_INVALID_ENUM );
	glReadPixels( 0, 0, -1, 1, GL_RGBA, GL_UNSIGNED_BYTE, px );
	Check( "negative read size gives INVALID_VALUE", glGetError() == GL_INVALID_VALUE );
}

// ---- vertex array objects ----
static void TestVao()
{
	static const uint16_t indices[6] = { 0, 1, 2, 3, 4, 5 };
	GLuint red = MakeQuad( -1, -1, 1, 1, 1, 0, 0 );
	GLuint green = MakeQuad( -1, -1, 1, 1, 0, 1, 0 );
	GLuint blue = MakeQuad( -1, -1, 1, 1, 0, 0, 1 );
	GLuint vaos[2];
	glGenVertexArrays( 2, vaos );
	Check( "a generated name is not a VAO until bound", !glIsVertexArray( vaos[0] ) );

	glBindVertexArray( vaos[0] );
	GLuint ibA = MakeBuffer( GL_ELEMENT_ARRAY_BUFFER, indices, sizeof( indices ) );
	UseQuad( green );
	glBindVertexArray( vaos[1] );
	GLuint ibB = MakeBuffer( GL_ELEMENT_ARRAY_BUFFER, indices, sizeof( indices ) );
	UseQuad( blue );
	glBindVertexArray( 0 );
	UseQuad( red );

	GLint v = -1;
	Check( "a bound name is a VAO", glIsVertexArray( vaos[0] ) == GL_TRUE );
	glGetIntegerv( GL_ELEMENT_ARRAY_BUFFER_BINDING, &v );
	Check( "default VAO has no index buffer", v == 0 );
	glBindVertexArray( vaos[0] );
	glGetIntegerv( GL_ELEMENT_ARRAY_BUFFER_BINDING, &v );
	Check( "VAO A remembers its index buffer", v == (GLint)ibA );
	glBindVertexArray( vaos[1] );
	glGetIntegerv( GL_ELEMENT_ARRAY_BUFFER_BINDING, &v );
	Check( "VAO B remembers its index buffer", v == (GLint)ibB );

	glBindVertexArray( vaos[0] );
	ClearWhite();
	glDrawElements( GL_TRIANGLES, 6, GL_UNSIGNED_SHORT, 0 );
	Check( "VAO A draws green", PixelIs( 32, 32, 0, 255, 0 ) );
	glBindVertexArray( vaos[1] );
	ClearWhite();
	glDrawElements( GL_TRIANGLES, 6, GL_UNSIGNED_SHORT, 0 );
	Check( "VAO B draws blue", PixelIs( 32, 32, 0, 0, 255 ) );
	glBindVertexArray( vaos[0] );
	ClearWhite();
	glDrawElements( GL_TRIANGLES, 6, GL_UNSIGNED_SHORT, 0 );
	Check( "VAO A is still green after using B", PixelIs( 32, 32, 0, 255, 0 ) );
	glBindVertexArray( 0 );
	ClearWhite();
	glDrawArrays( GL_TRIANGLES, 0, 6 );
	Check( "default VAO keeps its own state", PixelIs( 32, 32, 255, 0, 0 ) );

	// a disabled attribute reads as (0, 0, 0, 1), and that must stay inside this VAO
	glDisableVertexAttribArray( s_aColor );
	ClearWhite();
	glDrawArrays( GL_TRIANGLES, 0, 6 );
	Check( "a disabled colour attribute draws black", PixelIs( 32, 32, 0, 0, 0 ) );
	glBindVertexArray( vaos[0] );
	ClearWhite();
	glDrawElements( GL_TRIANGLES, 6, GL_UNSIGNED_SHORT, 0 );
	Check( "disabling in one VAO does not affect another", PixelIs( 32, 32, 0, 255, 0 ) );
	glBindVertexArray( 0 );
	glEnableVertexAttribArray( s_aColor );

	glBindVertexArray( vaos[1] );
	glDeleteVertexArrays( 1, &vaos[1] );
	glGetIntegerv( 0x85B5, &v );		// VERTEX_ARRAY_BINDING
	Check( "deleting the bound VAO returns to the default one", v == 0 );
	Check( "a deleted VAO is gone", !glIsVertexArray( vaos[1] ) );
	glBindVertexArray( vaos[1] );
	Check( "binding a deleted VAO is an error", glGetError() == GL_INVALID_OPERATION );
	glDeleteVertexArrays( 1, &vaos[0] );
}

// ---- glReadPixels on a framebuffer object ----
static void DrawHalves( GLuint bottom, GLuint top )
{
	ClearWhite();
	UseQuad( bottom );
	glDrawArrays( GL_TRIANGLES, 0, 6 );
	UseQuad( top );
	glDrawArrays( GL_TRIANGLES, 0, 6 );
}

static void TestRead()
{
	GLuint bottom = MakeQuad( -1, -1, 1, 0, 0, 1, 0 );		// green, lower half
	GLuint top = MakeQuad( -1, 0, 1, 1, 1, 0, 0 );			// red, upper half
	GLuint all = MakeQuad( -1, -1, 1, 1, 0, 0, 1 );
	DrawHalves( bottom, top );
	Check( "row 0 is the bottom of the picture", PixelIs( 32, 2, 0, 255, 0 ) );
	Check( "the last row is the top of the picture", PixelIs( 32, 61, 255, 0, 0 ) );

	uint8_t px[64];
	memset( px, 0xAB, sizeof( px ) );
	glReadPixels( 10, 61, 1, 1, 0x80E1, GL_UNSIGNED_BYTE, px );	// BGRA
	Check( "BGRA order", Near( px, 0, 0, 255, 255 ) );

	memset( px, 0xAB, sizeof( px ) );
	glReadPixels( 10, 2, 3, 2, GL_RGB, GL_UNSIGNED_BYTE, px );	// rows are padded to 4 bytes: 12 per row
	Check( "RGB pixels", px[0] < 3 && px[1] > 252 && px[2] < 3 && px[12] < 3 && px[13] > 252 );
	Check( "row padding is skipped", px[9] == 0xAB && px[10] == 0xAB && px[11] == 0xAB );

	glPixelStorei( GL_PACK_ALIGNMENT, 1 );
	memset( px, 0xAB, sizeof( px ) );
	glReadPixels( 10, 2, 3, 2, GL_RGB, GL_UNSIGNED_BYTE, px );
	Check( "PACK_ALIGNMENT 1 packs rows tightly", px[9] < 3 && px[10] > 252 && px[18] == 0xAB );
	glPixelStorei( GL_PACK_ALIGNMENT, 4 );

	memset( px, 0xAB, sizeof( px ) );
	glReadPixels( -2, 2, 4, 1, GL_RGBA, GL_UNSIGNED_BYTE, px );
	Check( "pixels left of the target are untouched", px[0] == 0xAB && px[7] == 0xAB && Near( px + 8, 0, 255, 0, 255 ) );
	memset( px, 0xAB, sizeof( px ) );
	glReadPixels( 62, 2, 4, 1, GL_RGBA, GL_UNSIGNED_BYTE, px );
	Check( "pixels right of the target are untouched", Near( px, 0, 255, 0, 255 ) && px[8] == 0xAB && px[15] == 0xAB );

	GLuint pbo;
	glGenBuffers( 1, &pbo );
	glBindBuffer( 0x88EB, pbo );								// PIXEL_PACK_BUFFER
	glBufferData( 0x88EB, 16, NULL, GL_STREAM_DRAW );
	glReadPixels( 32, 61, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, (void *)4 );
	const uint8_t *mapped = (const uint8_t *)glMapBufferRange( 0x88EB, 0, 16, 1 );
	Check( "reading into a pixel buffer", mapped && Near( mapped + 4, 255, 0, 0, 255 ) );
	glUnmapBuffer( 0x88EB );
	glBindBuffer( 0x88EB, 0 );

	UseQuad( all );
	glDrawArrays( GL_TRIANGLES, 0, 6 );
	Check( "drawing continues after a read", PixelIs( 32, 32, 0, 0, 255 ) );
	Check( "no errors in valid reads", glGetError() == GL_NO_ERROR );
}

// ---- glReadPixels on the screen ----
static void TestScreen( const char *name, GLuint bottom, GLuint top )
{
	glBindFramebuffer( GL_FRAMEBUFFER, 0 );
	glViewport( 0, 0, 1920, 1080 );
	DrawHalves( bottom, top );
	bool ok = PixelIs( 960, 10, 0, 255, 0 ) && PixelIs( 960, 1069, 255, 0, 0 );
	Check( name, ok );
}

int main()
{
	if ( !ps4glInit( 0 ) )
		for ( ;; ) {}

	s_prog = glCreateProgram();
	GLuint vs = glCreateShader( GL_VERTEX_SHADER ), ps = glCreateShader( GL_FRAGMENT_SHADER );
	glShaderBinary( 1, &vs, 0, g_color_vert, sizeof( g_color_vert ) );
	glShaderBinary( 1, &ps, 0, g_color_frag, sizeof( g_color_frag ) );
	glAttachShader( s_prog, vs );
	glAttachShader( s_prog, ps );
	glLinkProgram( s_prog );
	glUseProgram( s_prog );
	s_aPos = glGetAttribLocation( s_prog, "a_pos" );
	s_aColor = glGetAttribLocation( s_prog, "a_color" );
	s_uOffset = glGetUniformLocation( s_prog, "u_offset" );
	glUniform4f( s_uOffset, 0, 0, 0, 0 );
	glDisable( GL_DEPTH_TEST );
	glDisable( GL_CULL_FACE );

	GLuint tex, fbo;
	glGenTextures( 1, &tex );
	glBindTexture( GL_TEXTURE_2D, tex );
	glTexParameteri( GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST );
	glTexParameteri( GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST );
	glTexImage2D( GL_TEXTURE_2D, 0, GL_RGBA, 64, 64, 0, GL_RGBA, GL_UNSIGNED_BYTE, NULL );
	glGenFramebuffers( 1, &fbo );
	glBindFramebuffer( GL_FRAMEBUFFER, fbo );
	glFramebufferTexture2D( GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, tex, 0 );
	glViewport( 0, 0, 64, 64 );

	TestErrors();
	glViewport( 0, 0, 64, 64 );
	TestVao();
	TestRead();

	glBindFramebuffer( GL_FRAMEBUFFER, 77777 );
	uint8_t px[4];
	glReadPixels( 0, 0, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, px );
	Check( "reading a missing framebuffer is an error", glGetError() == GL_INVALID_FRAMEBUFFER_OPERATION );

	GLuint bottom = MakeQuad( -1, -1, 1, 0, 0, 1, 0 ), top = MakeQuad( -1, 0, 1, 1, 1, 0, 0 );
	TestScreen( "reading the screen at 1080p", bottom, top );
	ps4glSwapBuffers();
	ps4glSetSupersampling( 2 );
	ps4glSwapBuffers();
	Check( "supersampling is on", ps4glGetSupersampling() == 2 );
	TestScreen( "reading the screen with supersampling", bottom, top );
	ps4glSwapBuffers();
	ps4glSetSupersampling( 1 );
	ps4glSwapBuffers();

	// a read in every frame for two seconds: nothing may hang or fall out of step
	int good = 0;
	for ( int i = 0; i < 120; i++ )
	{
		DrawHalves( bottom, top );
		if ( PixelIs( 960, 10, 0, 255, 0 ) ) good++;
		ps4glSwapBuffers();
	}
	Check( "120 frames with a read in each", good == 120 );
	Check( "no errors at the end", glGetError() == GL_NO_ERROR );

	ps4glLog( "selftest: %d passed, %d failed", s_passed, s_failed );
	glClearColor( s_failed ? 0.8f : 0.0f, s_failed ? 0.0f : 0.7f, 0.1f, 1.0f );
	for ( ;; )
	{
		glClear( GL_COLOR_BUFFER_BIT );
		ps4glSwapBuffers();
	}
}
